// Read-only TypeScript diagnostics for a set of files in a given project root.
// Usage: node diag.js <projectRoot> <outFile> <fileListFile>
const path = require('path');
const fs = require('fs');
const [root, outFile, listFile] = process.argv.slice(2);
const ts = require('/Users/stark/Desktop/work/RN/csx-mobile/node_modules/typescript');

const files = fs.readFileSync(listFile, 'utf8').split('\n').filter(Boolean);
const cfgPath = path.join(root, 'tsconfig.json');
const cfg = ts.getParsedCommandLineOfConfigFile(cfgPath, {}, {
  ...ts.sys,
  onUnRecoverableConfigFileDiagnostic: (d) => console.error('CONFIG', ts.flattenDiagnosticMessageText(d.messageText, '\n')),
});
const options = {
  ...cfg.options,
  noEmit: true,
  incremental: false,
  tsBuildInfoFile: undefined,
  paths: {
    'react-native-toast-notifications': ['/tmp/cr552/package'],
    ...cfg.options.paths,
  },
};
console.error('root files:', cfg.fileNames.length, 'config errors:', cfg.errors.length);
const program = ts.createProgram({ rootNames: cfg.fileNames, options });
const out = [];
const coverage = [];
for (const rel of files) {
  const abs = path.join(root, rel);
  const sf = program.getSourceFile(abs);
  if (!sf) {
    coverage.push(`${rel}\tNOT_IN_PROGRAM`);
    continue;
  }
  const groups = [
    ['syn', program.getSyntacticDiagnostics(sf)],
    ['sem', program.getSemanticDiagnostics(sf)],
    ['sug', program.getSuggestionDiagnostics(sf)],
  ];
  const counts = [];
  for (const [kind, diags] of groups) {
    counts.push(`${kind}=${diags.length}`);
    for (const d of diags) {
      const { line } = d.file ? d.file.getLineAndCharacterOfPosition(d.start) : { line: -1 };
      const text = d.file ? d.file.text.split('\n')[line].trim().slice(0, 160) : '';
      const msg = ts.flattenDiagnosticMessageText(d.messageText, ' ').slice(0, 300);
      out.push([rel, kind, `TS${d.code}`, line + 1, msg, text, d.reportsDeprecated ? 'DEPRECATED' : ''].join('\t'));
    }
  }
  coverage.push(`${rel}\t${counts.join(' ')}`);
}
fs.writeFileSync(outFile, out.join('\n') + '\n');
fs.writeFileSync(outFile + '.coverage', coverage.join('\n') + '\n');
console.error('done', out.length);
